import type { INestApplication } from '@nestjs/common';
import { I18n, loadCatalogs } from '@nestvexa/i18n';
import type { I18nOptions } from '@nestvexa/i18n';
import { HbsEngine } from 'nestvexa';
import { resolve } from 'node:path';

/** Allowlisted locales; add a folder under locales/ for each. */
export const locales = ['en'];

/** Generated by `nestvexa add i18n`: catalogs are read once at startup. */
export async function i18nOptions(): Promise<I18nOptions> {
  return {
    locales,
    defaultLocale: 'en',
    timeZone: 'UTC',
    catalogs: await loadCatalogs(resolve(process.cwd(), 'locales'), {
      locales,
    }),
  };
}

/** Registers {{t}}, {{formatDate}}, ... with Handlebars. Call before configureNestvexa(app). */
export function configureI18n(app: INestApplication): void {
  app.get(HbsEngine).registerHelpers(app.get(I18n).helpers());
}
